10	export function useInputHistory({ text, setText, onHeightChange }: UseInputHistoryOptions) {
11	  const [history, setHistory] = useState<string[]>([]);
12	  const [index, setIndex] = useState(-1);
13	
14	  useEffect(() => {
15	    bridge.getInputHistory().then(setHistory);
16	  }, []);
17	
