19	    const trimmed = input.trim();
20	    if (!trimmed) {
21	      return;
22	    }
23	
24	    bridge.addInputHistory(trimmed);
25	    setHistory((prev) => (prev[prev.length - 1] === trimmed ? prev : [...prev, trimmed]));
26	    setIndex(-1);
27	  }, []);
28	
29	  const handleKey = useCallback(
30	    (e: React.KeyboardEvent): boolean => {
31	      // Ignore if any modifier key is pressed
32	      if (e.ctrlKey || e.metaKey || e.altKey) {
33	        return false;
34	      }
35	
36	      if (e.key === "ArrowUp" && history.length > 0 && (!text || index >= 0)) {
37	        const newIndex = Math.min(index + 1, history.length - 1);
38	        if (newIndex !== index) {
39	          e.preventDefault();
40	          setIndex(newIndex);
41	          setText(history[history.length - 1 - newIndex]);
42	          onHeightChange?.();
43	          return true;
